% mathsmap-diagram-colours {"version":1,"kind":"geometry","base":[],"semantic":[],"reference":"source PDF page 13, p13-q12-diagram"}
\begin{tikzpicture}[line cap=round,line join=round,font=\fontsize{10}{12}\selectfont]
\usetikzlibrary{calc,angles,quotes}
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
% Rectangular wedge model: O=(0,0,0), A=(L,0,0), C=(0,d,0), B=(L,d,0), Y=(0,d,h), X=(L,d,h).
% Projection basis: L -> (4,0.45), d -> (-1.18,1), h -> (0,2).
% Faces: OCY, ABX, OABC, CBXY, OAXY. Observer direction proportional to (-2.36,-8,4.531).
% CB and BA are hidden solid edges. BX is also hidden geometrically; its source-solid stroke is retained as the height construction used by triangle OBX.
\coordinate (O) at (0,0);
\coordinate (A) at (4,0.45);
\coordinate (C) at (-1.18,1);
\coordinate (B) at (2.82,1.45);
\coordinate (Y) at (-1.18,3);
\coordinate (X) at (2.82,3.45);
% Visible solid boundary, with no face fill.
\draw[black,line width=0.8pt] (O)--(C)--(Y)--(X)--(A)--cycle;
\draw[black,line width=0.8pt] (O)--(Y);
% Hidden solid edges.
\draw[black,line width=0.8pt,dashed] (C)--(B)--(A);
\draw[black,line width=0.8pt,dashed] (B)--(X);
% Source-supplied construction segments.
\draw[black,line width=0.8pt] (O)--(B) (O)--(X) (B)--(X);
% Coordinate-derived right-angle marks.
\coordinate (Cu) at ($(C)!0.15cm!(O)$);
\coordinate (Cv) at ($(C)!0.15cm!(Y)$);
\draw[black,line width=0.4pt] (Cu)--($(Cu)+(Cv)-(C)$)--(Cv);
\coordinate (Bu) at ($(B)!0.15cm!(O)$);
\coordinate (Bv) at ($(B)!0.15cm!(X)$);
\draw[black,line width=0.4pt] (Bu)--($(Bu)+(Bv)-(B)$)--(Bv);
% Angle sectors follow their actual source rays.
\pic[draw=black,line width=0.4pt,angle radius=0.49cm,angle eccentricity=1.3,"$\beta$"] {angle=Y--O--C};
\pic[draw=black,line width=0.4pt,angle radius=0.43cm,angle eccentricity=1.35,"$\alpha$"] {angle=X--O--Y};
\pic[draw=black,line width=0.4pt,angle radius=0.68cm,angle eccentricity=1.2,"$\theta$"] {angle=B--O--X};
\foreach \P in {O,A,C,B,Y,X} {\fill[black] (\P) circle[radius=0.7pt];}
\path (O) node[below left] {$O$}
(A) node[below right] {$A$}
(C) node[left] {$C$}
(B) node[right=6pt,yshift=5pt] {$B$}
(Y) node[above left] {$Y$}
(X) node[above] {$X$};
\end{tikzpicture}
